-- Direct organization rollout explicitly authorized by Steve McCutcheon on 2026-10-24.
-- No fabricated pilots, external reviews, signatures, training completion, payments or permission grants.
ALTER TABLE enrollment_rollout ADD COLUMN activation_basis text NOT NULL DEFAULT 'pilot' CHECK(activation_basis IN ('pilot','owner-directed'));
ALTER TABLE enrollment_rollout ADD COLUMN all_teams_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE handbook_documents DROP CONSTRAINT handbook_documents_kind_check;
ALTER TABLE handbook_documents ADD CONSTRAINT handbook_documents_kind_check CHECK(kind IN ('master','baseball','softball','medical','team','standards'));
INSERT INTO handbook_documents(id,kind) VALUES('organization-standards','standards');

CREATE TABLE enrollment_concussion_acknowledgments (
 id text PRIMARY KEY,case_id text NOT NULL REFERENCES enrollment_cases(id),guardian_id text NOT NULL,
 guardian_name text NOT NULL,athlete_name text NOT NULL,materials_version text NOT NULL,
 materials jsonb NOT NULL,statement text NOT NULL,acknowledged_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX enrollment_concussion_case_idx ON enrollment_concussion_acknowledgments(case_id,acknowledged_at);
ALTER TABLE enrollment_concussion_acknowledgments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON enrollment_concussion_acknowledgments FROM PUBLIC;
CREATE TRIGGER enrollment_concussion_immutable BEFORE UPDATE OR DELETE ON enrollment_concussion_acknowledgments FOR EACH ROW EXECUTE FUNCTION protect_handbook_audit();
CREATE TRIGGER enrollment_concussion_no_truncate BEFORE TRUNCATE ON enrollment_concussion_acknowledgments FOR EACH STATEMENT EXECUTE FUNCTION protect_handbook_audit();

-- The release directive applies to this existing academy, not an empty or synthetic installation.
-- On a new installation, verified owners can publish and activate through the normal scoped UI.
-- BEGIN OWNER AUTHORIZED PUBLICATION
DO $activation$
BEGIN
 IF EXISTS(SELECT 1 FROM club_state WHERE id='oklahoma-prospects' AND NOT demo)
 AND EXISTS(SELECT 1 FROM owner_grants g JOIN "user" u ON u.id=g.user_id JOIN profiles p ON p.user_id=u.id
   WHERE g.email='stevemccutcheon89@gmail.com' AND lower(trim(u.email))=g.email AND g.revoked_at IS NULL AND u."emailVerified"=true AND u."disabledAt" IS NULL AND p.role='admin')
 AND NOT EXISTS(SELECT 1 FROM handbook_audit WHERE id='organization-2026-10-24:activation') THEN
 INSERT INTO handbook_versions(document_id,version,effective_on,content,standards,review,content_hash,updated_by,status,published_by,published_at)
    SELECT 'academy-2027',coalesce(max(version),0)+1,'2026-10-24','{"title":"Prospects Sports Academy — Parent & Player Handbook","sections":[{"title":"Welcome and our commitment","body":"Welcome to Prospects Sports Academy. Since 2008, Prospects has brought baseball and softball families together around preparation, effort, accountability and player development. Ownership commits to communicating published season expectations, providing the agreed services, respecting athlete safety, and offering a clear path for concerns. Families commit to preparation, respectful conduct and their signed season obligations."},{"title":"How this handbook works","body":"These organization policies apply to Prospects Sports Academy baseball and softball teams and relevant academy activities. The sport supplement and published team standards explain additional expectations. Organization team standards apply when no team-specific addendum is published. Your separately accepted financial agreement controls the actual services, fees, installment dates and financial obligations. Cage rentals, lessons and memberships use their own purchase terms. This handbook does not amend an earlier agreement, release claims, expand a waiver or guarantee insurance coverage. Owners publish versioned changes with effective dates; material contractual changes require a separate agreement where applicable."},{"title":"Development and competition","body":"Prospects combines player development with competition. Movement, skill execution, decisions, preparation, confidence and consistency matter alongside game results. Every athlete receives instruction and feedback. Younger and developmental athletes receive meaningful opportunities to learn positions and skills; competitive situations also consider readiness, performance and strategy. Fees do not buy equal innings, a particular position, a roster promotion or a lineup spot. Coaches explain their approach through published team standards and private development conversations."},{"title":"Development feedback and training","body":"Each enrolled team athlete receives development goals within the first 30 days, at least one documented in-season update, and a final evaluation. A higher published team requirement still applies. A baseline assessment is recommended. Coaches record observed progress and next steps in the existing development workspace and distinguish measurements from estimates. A checklist does not complete an assessment, lesson or training assignment. Workload and goals must respect age, experience, recovery and medical restrictions. Private lessons and other optional services are included only when stated in the accepted offer."},{"title":"Attendance and preparation","body":"For a planned absence, notify the coach at least 48 hours before practice or 14 calendar days before a tournament. Record availability in the team account and contact the coach directly unless the team’s published standards accept the account notice as sufficient. If a conflict, emergency, illness, injury or late schedule change becomes known after that deadline, communicate as soon as reasonably possible. Notify the coach before arriving late or leaving early. Notice does not automatically excuse an absence, but legitimate medical restrictions, emergencies and an impossible notice deadline are not automatic disciplinary violations. Coaches discuss recurring avoidable absences privately and document the response."},{"title":"Conduct and discipline","body":"Players, families and staff must treat others respectfully. Bullying, hazing, discrimination, retaliation, threats, abusive coaching, physical punishment, harassment and equipment abuse are prohibited. Routine misconduct receives a proportionate verbal warning, written warning, temporary restriction and, when warranted, removal. Serious safety concerns permit immediate protective action. For nonemergency permanent removal, ownership reviews the facts, gives the family a chance to respond, and issues a written decision. A family may request review by the other owner within 10 calendar days. Safety reporting never has to wait for this process. Financial adjustments follow the existing signed agreement and applicable rights, not an automatic punishment created by this handbook."},{"title":"Communication and concerns","body":"Start routine schedule or development questions with the head coach. Staff should acknowledge routine messages within 48 hours; allow until the next day for a heated, nonurgent game disagreement. Escalate unresolved operational concerns to the authorized sport coordinator and then ownership. Only Steve and Nolan administer finances. Safety concerns, suspected abuse, discrimination, medical restrictions and emergencies bypass both the coach-first rule and any cooling-off period. No person is required to report only to the subject of a concern."},{"title":"Season fees and optional services","body":"Before acceptance, your account shows the owner-published team fee, included services, installment amounts and due dates. The usual new-season schedule is 70%, 15%, 15%, subject to the actual published plan and any retained agreement. The Team & Development Program amount comes from the owner-approved team configuration; this handbook sets no dollar amount and changes no pricing formula. Individual facility access is an optional selection with separate disclosed benefits and terms. Do not assume team enrollment includes unlimited cage use, private lessons or every membership product. Only verified payments and approved ledger credits affect the account."},{"title":"Withdrawal, injury and cancellation","body":"Submit a season withdrawal request to Steve or Nolan in writing. The signed season agreement and applicable law determine refunds and remaining obligations; injury, schedule conflicts and playing-time concerns do not automatically cancel it. Medical restrictions remain in force regardless of account status. If Prospects cancels a team or cannot deliver the agreed season, ownership gives the family an itemized decision within 30 calendar days, identifying delivered services, documented nonrecoverable commitments and unspent or recoverable funds. Refunds, credits and any deduction must be permitted by the signed agreement and applicable law. A canceled team is not treated as a family’s voluntary withdrawal. Cage, lesson and membership cancellation policies do not govern a seasonal team withdrawal."},{"title":"Replacement players and financial adjustments","body":"Only Steve or Nolan may approve a replacement offer, release an obligation, issue a refund or apply a credit. The written review identifies delivered services, unavoidable commitments, recoverable costs and new player-specific expenses. Prospects will not recover the same expense twice from departing and replacement families. Record an approved adjustment separately and preserve the original agreement. Coaches and coordinators cannot promise a refund, change a balance or collect an unapproved fee."},{"title":"Fundraising and assistance","body":"Prospects does not currently offer organization-funded scholarships, hardship exemptions or alternative payment arrangements. Approved fundraising may reduce outstanding obligations. Individual credits follow fundraiser terms and donor restrictions; team-wide net proceeds follow the allocation disclosed in advance. Expenses, proceeds and credits must be recorded through the authorized ledger. Extra proceeds do not automatically become cash payouts. Families can review their own financial account; other families’ balances and organization budgets remain private."},{"title":"Athlete protection","body":"Adults with regular athlete access must satisfy applicable background screening and athlete-protection training before service, including contractors and volunteers. No one may treat enrollment activation as proof that these requirements were completed. Activities must be observable and interruptible. Include a guardian or another authorized adult in communications with minors; do not use disappearing messages or secret one-to-one contact. No hazing, sexual misconduct, grooming, corporal punishment or retaliation is permitted. Anyone suspecting child abuse or neglect must report directly to Oklahoma’s 24-hour Abuse and Neglect Hotline, 1-800-522-3511; call 911 for immediate danger. An internal report does not replace an external report or delay it."},{"title":"Safety contacts and escalation","body":"Steve McCutcheon is the primary organization safety contact at stevemccutcheon89@gmail.com. Nolan McCutcheon is the alternate at nolanmccutcheon@icloud.com. Concerns involving Steve go directly to Nolan; concerns involving Nolan go directly to Steve. If both are involved, or an internal response is unsafe or inadequate, contact the appropriate outside authority directly. Use the restricted account safety form for nonurgent reports; these inboxes are not emergency dispatch and are not represented as monitored continuously. Call 911 for immediate danger and 1-800-522-3511 for suspected child abuse or neglect. Do not post safety reports or medical details in team messages. Ownership limits disclosure to those who need it to respond and preserves reporting records."},{"title":"Medical information and return to activity","body":"Guardians maintain current emergency contacts, relevant medical alerts and activity restrictions through the private enrollment form. Owners review these records and communicate the minimum necessary participation restrictions or emergency instructions to assigned staff; full medical records do not become team or coordinator records. A parent should also tell the coach about an immediate restriction. Stop activity that causes pain or unsafe symptoms. Only a qualified healthcare professional can provide a diagnosis or required return-to-play clearance. Enrollment clearance, a paid fee and a general waiver never override medical restrictions. Staff may share necessary information with emergency responders when responding to an emergency."},{"title":"Facility and equipment","body":"Use the Prospects Sports Facility, 3804 S. Elm Pl., Suite A, Broken Arrow, OK 74011, only for an authorized booking or scheduled activity. A responsible adult must supervise minors; a membership or access credential does not authorize unattended activity. Staff identify safe boundaries, exits and equipment rules before use. Use appropriate helmets, protective screens and sport-specific protective equipment; only an authorized adult operates a pitching machine. Keep spectators and siblings clear of active lanes, return equipment and report hazards immediately. Each participating athlete needs the current required waiver. Booking availability and purchase terms govern optional access; team enrollment does not promise unlimited facility use."},{"title":"Travel and supervision","body":"Parents arrange and remain responsible for transportation, lodging, meals and supervision outside official team activity. Prospects does not provide transportation or hotel supervision through team enrollment. A guardian may identify a responsible adult aged 18 or older as a private travel contact, but that does not transfer legal custody, authorize a coach to transport a minor, or establish insurance coverage. Organization-arranged travel or transport requires a separate owner-approved arrangement and verified applicable coverage before it occurs. Staff remain responsible for supervision during official practices, games, warmups and coach-directed activity."},{"title":"Privacy, media and technology","body":"Guardians use the family account for their own athletes. Do not let a child independently provide required enrollment or medical information through an adult account. Medical details and safety reports are restricted; operational staff receive only their authorized team information and completion status. Photos/video consent is a separate optional choice that may be declined without blocking enrollment and withdrawn for future use. Public roster and recruiting permissions remain separate. Do not publish minor contact information, medical information or private evaluations. Families may contact ownership to request access, correction or deletion of their records, subject to documented legal, safety and record-retention obligations. Current privacy and account terms continue to apply."},{"title":"First 30 days","body":"Activate the correct guardian account, review your team packet and published financial offer, complete required signatures and emergency information, and verify the deposit. Submit uniform sizes, meet the coach, review the schedule and facility rules, and establish development goals. The team checklist records orientation and baseline assessment only when actually completed. A family can still access its documents, payment steps and safety contact while enrollment requirements are incomplete."},{"title":"Versions and acknowledgment","body":"The account retains the exact policy versions, signer names, acknowledgment text and date accepted by the guardian. Existing financial agreements and earlier signatures remain intact. Electronic acknowledgment is voluntary; contact ownership for an accessible or paper process when needed. Payment is not a signature, and a signature is not payment or medical clearance. Optional media consent is separate. Organization activation makes the enrollment workflow available; it does not assert that any athlete, staff member, venue or insurance requirement is already cleared."},{"title":"Concussion education and participation","body":"Before participation and annually, athletes and guardians receive concussion information and acknowledge it. All team and game officials complete annual comparable concussion training; ownership maintains completion records. A suspected concussion means immediate removal, no same-day return and written healthcare-provider clearance. Staff who fail to remove an athlete or bypass clearance are removed from duty pending owner review, retraining and a documented decision; serious or repeated violations can end the assignment. Steve and Nolan review this policy annually. The enrollment workspace supplies the athlete/guardian acknowledgment and Oklahoma/CDC educational resources."},{"title":"Emergency-response plan","body":"Before every practice or event, the supervising coach identifies the exact venue address, emergency access route, shelter, first-aid resources, available AED and the adults assigned to call 911, meet responders, supervise the other athletes and contact guardians. Check equipment and access before activity; do not assume an AED or trained responder is available. For an emergency, stop activity, call 911 with the exact location, follow dispatcher instructions and provide only aid within your training. Do not move a potentially serious head/neck injury unless needed to avoid immediate danger or directed by emergency personnel. Notify the guardian and ownership promptly and record the incident privately. Staff review this plan during team orientation and adapt it to each away venue."},{"title":"Weather, heat and hydration","body":"The supervising coach monitors conditions before and during activity and may stop activity for safety regardless of tournament pressure. On hearing thunder or seeing lightning, stop outdoor activity and move everyone to a substantial enclosed building or enclosed hard-topped vehicle; dugouts and open shelters are inadequate. Wait at least 30 minutes after the last thunder or lightning before resuming. Adjust activity for heat, humidity and athlete acclimatization; provide water, cooling breaks and access to shade or a cool location. Stop activity for concerning symptoms, move the athlete to safety and seek appropriate medical help; call 911 for collapse, confusion or another emergency. Follow stricter venue or governing-body requirements."},{"title":"Insurance and incident records","body":"Insurance coverage is determined by the actual applicable policies, endorsements, exclusions and insurer decisions. This handbook and enrollment activation do not certify coverage or promise payment of an injury claim. Owners maintain the relevant insurance records, verify that operations and venues are covered, and notify the insurer as required after an incident. Staff preserve factual incident records and do not promise that a claim will be paid. Existing waivers and financial agreements remain separate; no new release of liability is created by this acknowledgment."}]}'::jsonb,NULL,'{"legalReviewer":"","legalReviewedOn":"","insuranceReviewer":"","insuranceReviewedOn":"","reviewReference":""}'::jsonb,'e2e032d390541a320b29e2276896d8889dd1a778f78ad3f6d0a85474b5ff6428','system:owner-authorized-release','published','system:owner-authorized-release',now() FROM handbook_versions WHERE document_id='academy-2027';
  INSERT INTO handbook_audit(id,actor_id,action,target_id,details) VALUES('organization-2026-10-24:academy-2027','system:owner-authorized-release','handbook.publish','academy-2027','{"authorization":"Steve McCutcheon explicitly requested policy revision, publication and direct organization-wide activation on 2026-10-24.","policyRelease":"organization-2026-10-24","hash":"e2e032d390541a320b29e2276896d8889dd1a778f78ad3f6d0a85474b5ff6428","externalLegalApproval":false,"externalInsuranceApproval":false}'::jsonb);
INSERT INTO handbook_versions(document_id,version,effective_on,content,standards,review,content_hash,updated_by,status,published_by,published_at)
    SELECT 'baseball-2027',coalesce(max(version),0)+1,'2026-10-24','{"title":"Prospects Baseball Supplement","sections":[{"title":"Baseball development","body":"Coaches adapt hitting, fielding, baserunning, catching, throwing and situational instruction to age, experience and the team’s developmental or competitive designation. Younger athletes should have meaningful opportunities to learn and explore positions without a promise of equal playing time. Individual goals and reassessments use the existing development record."},{"title":"Throwing and pitching","body":"Follow the applicable tournament, league and adopted age-specific pitching and rest rules. Include outside-team throwing when discussing workload. Report arm pain immediately, stop painful activity, and respect medical restrictions. No universal pitch-count number is established by this handbook; approved current rules and individualized medical advice govern."},{"title":"Competition and equipment","body":"The coach confirms age eligibility, field dimensions, bat/equipment requirements, roster rules and guest-player eligibility for each competition. Published schedules remain subject to organizer changes. Catchers and field players use the required protective equipment. The team addendum establishes expectations before enrollment."}]}'::jsonb,NULL,'{"legalReviewer":"","legalReviewedOn":"","insuranceReviewer":"","insuranceReviewedOn":"","reviewReference":""}'::jsonb,'2fb1e9f5be120b29f61b32bb93396b14ad698a809b1526eaed1a6f990c33a743','system:owner-authorized-release','published','system:owner-authorized-release',now() FROM handbook_versions WHERE document_id='baseball-2027';
  INSERT INTO handbook_audit(id,actor_id,action,target_id,details) VALUES('organization-2026-10-24:baseball-2027','system:owner-authorized-release','handbook.publish','baseball-2027','{"authorization":"Steve McCutcheon explicitly requested policy revision, publication and direct organization-wide activation on 2026-10-24.","policyRelease":"organization-2026-10-24","hash":"2fb1e9f5be120b29f61b32bb93396b14ad698a809b1526eaed1a6f990c33a743","externalLegalApproval":false,"externalInsuranceApproval":false}'::jsonb);
INSERT INTO handbook_versions(document_id,version,effective_on,content,standards,review,content_hash,updated_by,status,published_by,published_at)
    SELECT 'softball-2027',coalesce(max(version),0)+1,'2026-10-24','{"title":"Prospects Softball Supplement","sections":[{"title":"Softball development","body":"Coaches adapt fastpitch hitting, pitch recognition, bunting, slapping, fielding, baserunning, catching and situational instruction to athlete age and experience. Team designation and playing-time expectations are communicated before enrollment. Progress includes skill, decisions, confidence and consistency."},{"title":"Throwing and pitching","body":"Windmill pitching workload, recovery and arm care require softball-specific planning. Baseball pitching limits must not be automatically substituted for softball guidance. Coaches follow applicable governing rules and adopted medical/sports-science guidance, discuss outside-team workload, stop painful activity and honor medical restrictions."},{"title":"Competition and equipment","body":"The coach confirms division and roster eligibility, field dimensions, lead-off rules, protective equipment and competition requirements for each event. Position development includes softball-specific short-game defense, receiving, blocking and throwing. The approved team addendum establishes practice and tournament commitments."}]}'::jsonb,NULL,'{"legalReviewer":"","legalReviewedOn":"","insuranceReviewer":"","insuranceReviewedOn":"","reviewReference":""}'::jsonb,'cbc5d7d1fba020447cf446986d2bf9cdb4edcde07787c7895e8defe36b2ccbf6','system:owner-authorized-release','published','system:owner-authorized-release',now() FROM handbook_versions WHERE document_id='softball-2027';
  INSERT INTO handbook_audit(id,actor_id,action,target_id,details) VALUES('organization-2026-10-24:softball-2027','system:owner-authorized-release','handbook.publish','softball-2027','{"authorization":"Steve McCutcheon explicitly requested policy revision, publication and direct organization-wide activation on 2026-10-24.","policyRelease":"organization-2026-10-24","hash":"cbc5d7d1fba020447cf446986d2bf9cdb4edcde07787c7895e8defe36b2ccbf6","externalLegalApproval":false,"externalInsuranceApproval":false}'::jsonb);
INSERT INTO handbook_versions(document_id,version,effective_on,content,standards,review,content_hash,updated_by,status,published_by,published_at)
    SELECT 'medical-2027',coalesce(max(version),0)+1,'2026-10-24','{"title":"Emergency Medical Authorization","sections":[{"title":"Emergency arrangements","body":"If my athlete needs urgent medical attention during an official Prospects activity and I cannot be reached promptly, I authorize staff to contact emergency services and arrange evaluation and transportation by qualified emergency personnel. Treatment decisions remain with qualified medical professionals under applicable law. Staff will attempt to notify me or my designated emergency contact as soon as practical; urgent care must not be delayed while waiting for a reply."},{"title":"Information and limits","body":"I will keep emergency contacts, relevant medical alerts and activity restrictions current. I authorize necessary information to be given to emergency responders for this purpose. This authorization does not authorize elective care, give coaches medical authority, waive nonwaivable rights, permit activity against medical restrictions, or replace a provider’s clearance. Medical costs and coverage are governed by applicable law, insurance and separate agreements; this form does not guarantee insurance payment or create a new release of liability."}]}'::jsonb,NULL,'{"legalReviewer":"","legalReviewedOn":"","insuranceReviewer":"","insuranceReviewedOn":"","reviewReference":""}'::jsonb,'b91f64df3df25a2bc1422f4515c2926445fff51d9e9617faac69965fb934b867','system:owner-authorized-release','published','system:owner-authorized-release',now() FROM handbook_versions WHERE document_id='medical-2027';
  INSERT INTO handbook_audit(id,actor_id,action,target_id,details) VALUES('organization-2026-10-24:medical-2027','system:owner-authorized-release','handbook.publish','medical-2027','{"authorization":"Steve McCutcheon explicitly requested policy revision, publication and direct organization-wide activation on 2026-10-24.","policyRelease":"organization-2026-10-24","hash":"b91f64df3df25a2bc1422f4515c2926445fff51d9e9617faac69965fb934b867","externalLegalApproval":false,"externalInsuranceApproval":false}'::jsonb);
INSERT INTO handbook_versions(document_id,version,effective_on,content,standards,review,content_hash,updated_by,status,published_by,published_at)
    SELECT 'organization-standards',coalesce(max(version),0)+1,'2026-10-24','{"title":"Prospects Sports Academy — Organization Team Standards","sections":[{"title":"Scope and playing time","body":"Prospects develops athletes while competing. Every roster athlete receives instruction, feedback and meaningful opportunities appropriate to readiness, age and the team’s competition. Equal innings, a fixed position, a batting-order spot and advancement are not promised. Coaches consider safety, preparation, effort, attendance, skill readiness and game strategy; concerns receive a private development discussion. A published team addendum may explain competitive expectations but cannot reduce organization safety or development minimums."},{"title":"Practices","body":"Attend the practices shown in the team calendar, arrive ready at the coach’s published reporting time, bring required equipment and water, and communicate conflicts. The published team offer controls the number and type of included practices; this standard adds no fee or unpromised training. Notify the coach promptly when a schedule is announced too late to meet the usual notice period."},{"title":"Tournaments and travel","body":"Families commit to the season schedule disclosed in their team offer and subsequently published calendar. The coach communicates organizer changes and travel requirements promptly. Added events or material financial changes require the applicable owner-approved agreement; coaches cannot create new family obligations through a calendar entry. Parents arrange transportation, lodging and supervision outside official team activity."},{"title":"Development feedback","body":"Use the existing athlete development record to set goals within the first 30 days, provide at least one documented in-season update and a final evaluation. Record observed skills, effort, decision-making and next steps; identify estimates and unverified measurements. A baseline assessment is recommended and is only recorded as completed after it actually occurs. Families may request a private review with the assigned coach."},{"title":"Communication","body":"Team account for schedules and availability; direct coach contact for an absence or urgent change; Steve or Nolan for financial matters; the published safety contacts for safety concerns"},{"title":"Notice and emergency exceptions","body":"Give 48 hours’ notice for a planned practice absence and 14 days for a planned tournament absence. Contact the coach directly as well as recording availability. Emergencies, medical restrictions and conflicts learned after the deadline are communicated as soon as reasonably possible and are not automatic disciplinary violations."},{"title":"Fees and individual addenda","body":"These minimum standards apply to every team without a published team-specific addendum. A team addendum may explain its competition and schedule but cannot reduce organization safety standards or required development feedback. Actual fees, services and dates remain those in the separately accepted owner-published financial agreement."}]}'::jsonb,'{"designation":"developmental","playingTime":"Prospects develops athletes while competing. Every roster athlete receives instruction, feedback and meaningful opportunities appropriate to readiness, age and the team’s competition. Equal innings, a fixed position, a batting-order spot and advancement are not promised. Coaches consider safety, preparation, effort, attendance, skill readiness and game strategy; concerns receive a private development discussion. A published team addendum may explain competitive expectations but cannot reduce organization safety or development minimums.","practiceExpectations":"Attend the practices shown in the team calendar, arrive ready at the coach’s published reporting time, bring required equipment and water, and communicate conflicts. The published team offer controls the number and type of included practices; this standard adds no fee or unpromised training. Notify the coach promptly when a schedule is announced too late to meet the usual notice period.","tournamentCommitment":"Families commit to the season schedule disclosed in their team offer and subsequently published calendar. The coach communicates organizer changes and travel requirements promptly. Added events or material financial changes require the applicable owner-approved agreement; coaches cannot create new family obligations through a calendar entry. Parents arrange transportation, lodging and supervision outside official team activity.","evaluationMethod":"Use the existing athlete development record to set goals within the first 30 days, provide at least one documented in-season update and a final evaluation. Record observed skills, effort, decision-making and next steps; identify estimates and unverified measurements. A baseline assessment is recommended and is only recorded as completed after it actually occurs. Families may request a private review with the assigned coach.","communicationChannel":"Team account for schedules and availability; direct coach contact for an absence or urgent change; Steve or Nolan for financial matters; the published safety contacts for safety concerns","rsvpIsNotice":false,"practiceNoticeHours":48,"tournamentNoticeDays":14,"inSeasonUpdates":1,"finalEvaluation":true}'::jsonb,'{"legalReviewer":"","legalReviewedOn":"","insuranceReviewer":"","insuranceReviewedOn":"","reviewReference":""}'::jsonb,'61ad768d24b6d604b918614005ea198c2c7a6e8ab4f2b153768a14273d7e7de3','system:owner-authorized-release','published','system:owner-authorized-release',now() FROM handbook_versions WHERE document_id='organization-standards';
  INSERT INTO handbook_audit(id,actor_id,action,target_id,details) VALUES('organization-2026-10-24:organization-standards','system:owner-authorized-release','handbook.publish','organization-standards','{"authorization":"Steve McCutcheon explicitly requested policy revision, publication and direct organization-wide activation on 2026-10-24.","policyRelease":"organization-2026-10-24","hash":"61ad768d24b6d604b918614005ea198c2c7a6e8ab4f2b153768a14273d7e7de3","externalLegalApproval":false,"externalInsuranceApproval":false}'::jsonb);
 UPDATE enrollment_rollout SET mode='organization',activation_basis='owner-directed',all_teams_enabled=true,
   safety_name='Steve McCutcheon',safety_contact='stevemccutcheon89@gmail.com',
   alternate_name='Nolan McCutcheon',alternate_contact='nolanmccutcheon@icloud.com',
   emergency_plan_reference='Published organization handbook: Emergency-response plan; supervising staff adapt the plan to each venue before activity.',
   revision=revision+1,updated_by='system:owner-authorized-release',updated_at=now() WHERE id='academy';
 INSERT INTO enrollment_additional_teams(team_id,sport,season_key,signatures_open,updated_by)
 SELECT t->>'id',t->>'sport',coalesce(nullif(trim(t->>'seasonLabel'),''),'2027'),true,'system:owner-authorized-release'
 FROM club_state c CROSS JOIN LATERAL jsonb_array_elements(c.payload->'teams') t
 WHERE c.id='oklahoma-prospects' AND NOT c.demo AND coalesce(t->>'closed','false')<>'true' AND t->>'sport' IN ('baseball','softball')
 AND NOT EXISTS(SELECT 1 FROM enrollment_pilots p WHERE p.team_id=t->>'id') ON CONFLICT DO NOTHING;
 INSERT INTO handbook_audit(id,actor_id,action,target_id,details) VALUES('organization-2026-10-24:activation','system:owner-authorized-release','rollout.organization','academy',
   '{"basis":"owner-directed","pilotRequired":false,"authorization":"Steve McCutcheon requested direct organization-wide activation on 2026-10-24","contactBasis":"Existing organization and owner contact addresses; no claim of continuous monitoring or a test message","externalLegalApproval":false,"externalInsuranceApproval":false}'::jsonb);
 END IF;
END $activation$;
-- END OWNER AUTHORIZED PUBLICATION
